  30	/// Flags the full binding-scoped flags that can be set per binding.
  31	pub const Flags = packed struct {
  32	    /// True if this binding should consume the input when the
  33	    /// action is triggered.
  34	    consumed: bool = true,
  35	
  36	    /// True if this binding should be forwarded to all active surfaces
  37	    /// in the application.
  38	    all: bool = false,
  39	
  40	    /// True if this binding is global. Global bindings should work system-wide
  41	    /// and not just while Ghostty is focused. This may not work on all platforms.
  42	    /// See the keybind config documentation for more information.
  43	    global: bool = false,
  44	
  45	    /// True if this binding should only be triggered if the action can be
  46	    /// performed. If the action can't be performed then the binding acts as
  47	    /// if it doesn't exist.
  48	    performable: bool = false,
  49	
  50	    /// C type
  51	    pub const C = u8;
  52	
  53	    /// Converts this to a C-compatible value.
  54	    ///
  55	    /// Sync with ghostty.h for enums.
  56	    pub fn cval(self: Flags) C {
  57	        const Backing = @typeInfo(Flags).@"struct".backing_integer.?;
  58	        return @as(Backing, @bitCast(self));
  59	    }
  60	
  61	    test "cval" {
  62	        const testing = std.testing;
  63	        try testing.expectEqual(@as(u8, 0b0001), (Flags{}).cval());
  64	        try testing.expectEqual(@as(u8, 0b0000), (Flags{ .consumed = false }).cval());
  65	        try testing.expectEqual(@as(u8, 0b0011), (Flags{ .all = true }).cval());
  66	        try testing.expectEqual(@as(u8, 0b0101), (Flags{ .global = true }).cval());
  67	        try testing.expectEqual(@as(u8, 0b1001), (Flags{ .performable = true }).cval());
  68	        try testing.expectEqual(@as(u8, 0b1111), (Flags{ .consumed = true, .all = true, .global = true, .performable = true }).cval());
  69	    }
